#!/usr/bin/env node
/**
 * Render canonical configuration into native Claude Code and OpenCode files.
 *
 * Canonical inputs:
 *   shared/models.json
 *   shared/rules/*.md
 *   shared/agents/*.json
 *   shared/agents/prompts/*.md
 *
 * Outputs:
 *   shared/AGENTS.md          (and a root AGENTS.md symlink)
 *   claude/agents/*.md
 *   opencode/agents/*.md
 *
 * Usage: node scripts/render.mjs [--check]
 *        --check exits 1 if any generated file is stale.
 */
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync, unlinkSync, symlinkSync, lstatSync } from "node:fs";
import { join, dirname, basename } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const CHECK = process.argv.includes("--check");
const failures = [];
const written = [];

const read = (path) => readFileSync(join(ROOT, path), "utf8");
const readJson = (path) => JSON.parse(read(path));
const yaml = (value) => JSON.stringify(String(value));

function ensureDir(path) {
  mkdirSync(join(ROOT, path), { recursive: true });
}

function emit(path, content) {
  const full = join(ROOT, path);
  const current = existsSync(full) ? readFileSync(full, "utf8") : null;
  if (current === content) return;
  if (CHECK) {
    failures.push(path);
    return;
  }
  ensureDir(dirname(path));
  writeFileSync(full, content, { mode: 0o644 });
  written.push(path);
}

function removeStale(dir, expected) {
  if (CHECK || !existsSync(join(ROOT, dir))) return;
  for (const name of readdirSync(join(ROOT, dir))) {
    if (!name.endsWith(".md") || expected.has(name)) continue;
    const full = join(ROOT, dir, name);
    const text = readFileSync(full, "utf8");
    if (text.includes("generated by nex/scripts/render.mjs")) {
      unlinkSync(full);
      written.push(`${dir}/${name} (removed)`);
    }
  }
}

// ---------------------------------------------------------------- instructions
const rulesDir = join(ROOT, "shared/rules");
const ruleFiles = readdirSync(rulesDir).filter((f) => f.endsWith(".md")).sort();
const ruleParts = ruleFiles.map((file) => {
  const body = readFileSync(join(rulesDir, file), "utf8").trim();
  return `<!-- source: shared/rules/${file} -->\n${body}`;
});
const agentsMd = [
  "<!-- generated by nex/scripts/render.mjs; edit shared/rules/*.md instead -->",
  "# Global agent rules",
  "",
  "These rules apply to every session in any supported AI provider (Claude Code,",
  "OpenCode, and others). Project-level instructions take precedence where they",
  "are more specific.",
  "",
  ruleParts.join("\n\n"),
  "",
].join("\n");
emit("shared/AGENTS.md", agentsMd);

// Root AGENTS.md as a relative symlink so a session started in ~/nex loads it.
const rootAgents = join(ROOT, "AGENTS.md");
if (!CHECK) {
  let isLink = false;
  try { isLink = lstatSync(rootAgents).isSymbolicLink(); } catch {}
  if (isLink) {
    // already a link; leave it
  } else if (existsSync(rootAgents)) {
    // Do not clobber a real file; the generated copy is authoritative.
  } else {
    symlinkSync("shared/AGENTS.md", rootAgents);
  }
}

// ---------------------------------------------------------------------- agents
const models = readJson("shared/models.json");
const agentDir = join(ROOT, "shared/agents");
const agentFiles = readdirSync(agentDir).filter((f) => f.endsWith(".json")).sort();
const expectedClaude = new Set();
const expectedOpencode = new Set();

for (const file of agentFiles) {
  const def = JSON.parse(readFileSync(join(agentDir, file), "utf8"));
  for (const key of ["id", "description", "mode", "profile"]) {
    if (!def[key]) throw new Error(`${file}: missing ${key}`);
  }
  if (!models.profiles[def.profile]) throw new Error(`${file}: unknown profile ${def.profile}`);
  if (!["primary", "subagent", "all"].includes(def.mode)) {
    throw new Error(`${file}: invalid mode ${def.mode}`);
  }
  const profile = models.profiles[def.profile];
  const promptPath = join(agentDir, "prompts", `${def.id}.md`);
  if (!existsSync(promptPath)) throw new Error(`${file}: missing prompt ${promptPath}`);
  const prompt = readFileSync(promptPath, "utf8").trim();

  // OpenCode: Markdown agent with V2 frontmatter.
  const oc = def.opencode ?? {};
  const ocLines = [
    "---",
    `description: ${yaml(def.description)}`,
    `mode: ${def.mode}`,
    `model: ${profile.opencode}`,
  ];
  if (oc.steps) ocLines.push(`steps: ${oc.steps}`);
  if (def.color) ocLines.push(`color: ${yaml(def.color)}`);
  if (Array.isArray(oc.permissions) && oc.permissions.length) {
    ocLines.push("permissions:");
    for (const rule of oc.permissions) {
      ocLines.push(`  - action: ${yaml(rule.action)}`);
      ocLines.push(`    resource: ${yaml(rule.resource)}`);
      ocLines.push(`    effect: ${yaml(rule.effect)}`);
    }
  }
  ocLines.push("---", "", `<!-- generated by nex/scripts/render.mjs from shared/agents/${file} -->`, "", prompt, "");
  const ocFile = `opencode/agents/${def.id}.md`;
  emit(ocFile, ocLines.join("\n"));
  expectedOpencode.add(`${def.id}.md`);

  // Claude Code: subagent frontmatter. Model aliases are accepted by Claude.
  const cl = def.claude ?? {};
  const clLines = [
    "---",
    `name: ${def.id}`,
    `description: ${yaml(def.description)}`,
    `model: ${profile.claude}`,
  ];
  if (Array.isArray(cl.tools) && cl.tools.length) clLines.push(`tools: ${cl.tools.join(", ")}`);
  if (cl.permissionMode) clLines.push(`permissionMode: ${cl.permissionMode}`);
  if (cl.maxTurns) clLines.push(`maxTurns: ${cl.maxTurns}`);
  clLines.push("---", "", `<!-- generated by nex/scripts/render.mjs from shared/agents/${file} -->`, "", prompt, "");
  const clFile = `claude/agents/${def.id}.md`;
  emit(clFile, clLines.join("\n"));
  expectedClaude.add(`${def.id}.md`);
}

removeStale("claude/agents", expectedClaude);
removeStale("opencode/agents", expectedOpencode);

// --------------------------------------------------------------------- summary
if (CHECK) {
  if (failures.length) {
    console.error("render --check: stale generated files:");
    for (const f of failures) console.error(`  ${f}`);
    console.error("Run: nex render");
    process.exit(1);
  }
  console.log("render --check: generated files are current");
} else {
  console.log(`render: ${ruleFiles.length} rule files, ${agentFiles.length} agents`);
  for (const f of written) console.log(`  wrote ${f}`);
  if (!written.length) console.log("  nothing changed");
}
